using System.Security.Cryptography;
using System.Text.Json;
namespace CMCutLab;
internal static class SelfTest
{
 internal static async Task<int> Smoke(string source){string root=Path.Combine(AppContext.BaseDirectory,"real-smoke");Directory.CreateDirectory(root);try{using var lease=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.Read);var original=new FileInfo(source);long size=original.Length;DateTime modified=original.LastWriteTimeUtc;string clip=Path.Combine(root,"read-only-sample.ts");await Engine.Run("ffmpeg",["-v","error","-nostdin","-y","-ss","30","-i",source,"-t","45","-map","0:v:0","-map","0:a:0?","-c","copy","-f","mpegts",clip],CancellationToken.None);var media=await Engine.Probe(clip,CancellationToken.None);using(var frame=await Engine.Frame(clip,3,CancellationToken.None))frame.Save(Path.Combine(root,"frame.png"));original.Refresh();if(original.Length!=size||original.LastWriteTimeUtc!=modified)throw new Exception("Original file metadata changed");File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=true,Source=source,SampleSeconds=media.Duration,OriginalUnchanged=true,Note="Real media read-only decode test"},new JsonSerializerOptions{WriteIndented=true}));return 0;}catch(Exception e){File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=false,Error=e.ToString()}));return 1;}}
 internal static async Task<int> Run(){string root=Path.Combine(AppContext.BaseDirectory,"test-output");Directory.CreateDirectory(root);var log=new List<string>();try{
 var merged=Engine.Keep([new(2,6,"test"){Selected=true},new(4,8,"test"){Selected=true}],10);if(merged.Count!=2||merged[0]!=(0d,2d)||merged[1]!=(8d,10d))throw new Exception("Overlapping cuts were not merged");
 var none=Engine.Keep([new(2,6,"unchecked")],10);if(none.Count!=1||none[0]!=(0d,10d))throw new Exception("Unchecked candidate removed footage");
 try{Engine.Keep([new(0,10,"whole"){Selected=true}],10);throw new Exception("Whole-file removal accepted");}catch(InvalidDataException){}log.Add("PASS checked cuts only; overlapping cuts unioned; whole-file removal rejected");
 string file=Path.Combine(root,"sample.ts");await Engine.Run("ffmpeg",["-hide_banner","-v","error","-nostdin","-y","-f","lavfi","-i","testsrc2=duration=25:size=320x180:rate=30","-f","lavfi","-i","sine=frequency=440:duration=25","-vf","drawbox=color=black:t=fill:enable='between(t,4.9,5.1)+between(t,19.9,20.1)'","-af","volume=0:enable='between(t,4.9,5.1)+between(t,19.9,20.1)'","-c:v","mpeg2video","-q:v","4","-c:a","mp2","-shortest",file],CancellationToken.None);
 byte[] original=SHA256.HashData(File.ReadAllBytes(file));var media=await Engine.Probe(file,CancellationToken.None);if(Math.Abs(media.Duration-25)>.2)throw new Exception("Probe duration wrong");log.Add("PASS source TS probe; manual edit only, no automatic CM detection");
 using(var frame=await Engine.Frame(file,3,CancellationToken.None)){if(frame.Width<=0||frame.Height<=0)throw new Exception("Frame missing");frame.Save(Path.Combine(root,"frame.png"));}log.Add("PASS frame preview extraction");
 var chosen=new Cut(5,20,"confirmed"){Selected=true};string output=Path.Combine(root,"sample-cut.mp4");if(File.Exists(output))File.Delete(output);await Engine.Export(file,output,media,Engine.Keep([chosen],25),"libsvtav1",2,CancellationToken.None,_=>{});var result=await Engine.Probe(output,CancellationToken.None);if(Math.Abs(result.Duration-10)>.25||Math.Abs(result.Fps-media.Fps)>.01||result.Width!=media.Width||result.Height!=media.Height)throw new Exception("Cut duration/size/fps mismatch");log.Add("PASS AV1 MP4 output duration approximately 10 seconds; source size and FPS retained");
 try{await Engine.Export(file,output,media,[(0,1)],"libsvtav1",2,CancellationToken.None,_=>{});throw new Exception("Existing output overwritten");}catch(IOException){}try{await Engine.Export(file,file,media,[(0,1)],"libsvtav1",2,CancellationToken.None,_=>{});throw new Exception("Source overwritten");}catch(IOException){}log.Add("PASS output collision and source overwrite refused");
 using(var cts=new CancellationTokenSource()){cts.Cancel();try{await Engine.Export(file,Path.Combine(root,"cancelled.mp4"),media,[(0,1)],"libsvtav1",2,cts.Token,_=>{});throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}}if(Directory.EnumerateFiles(root,".cmcut-*").Any()||File.Exists(Path.Combine(root,"cancelled.mp4")))throw new Exception("Temporary export left behind");if(!original.SequenceEqual(SHA256.HashData(File.ReadAllBytes(file))))throw new Exception("Source modified");log.Add("PASS cancelled export cleaned; source SHA256 unchanged");
 File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=true,Tests=log,Source=file,Output=output,Duration=result.Duration},new JsonSerializerOptions{WriteIndented=true}));return 0;
 }catch(Exception e){log.Add(e.ToString());File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{Passed=false,Tests=log},new JsonSerializerOptions{WriteIndented=true}));return 1;}}
}
